-- Weekly hours (EXAMPLE). Some are under the 10 h minimum or on approved leave, so they are unranked.

-- Example pilot season (EXAMPLE DATA): 6 weeks in of 12. Owner-only; length must be 10-12 weeks (CHECK).
-- Season Champion needs to be ranked in 60% of weeks (example, v7), i.e. 8 of 12.
values ('Pilot season (EXAMPLE)', (public.perth_week_start() - 42), 12, 60, (select id from public.staff where staff_code = 'OWNER'));

select l.staff_id, l.outlet_id, 'reversal', -l.points, 'Reversed: spot check failed, back on the list', l.completion_id, l.id, (select id from public.staff where staff_code = 'A-M2'), l.awarded_at + interval '1 hour'
  from public.points_ledger l where l.entry_type = 'award' and l.outlet_id = (select id from public.outlets where slug = 'boughshed-kitchen') and l.awarded_at < public.perth_today() - 9 order by l.id limit 2;
select r.staff_id, r.outlet_id, 'bonus', 10, 'Rush bonus: slammed Saturday service, close-down passed', (select id from public.staff where staff_code = 'A-M1'), least(((public.perth_today() - 9) + time '23:00') at time zone 'Australia/Perth', now() - interval '2 minutes')
  from public.roster_shifts r where r.outlet_id = (select id from public.outlets where slug = 'boughshed-kitchen') and r.shift_date = (public.perth_today() - 9) and r.shift in ('pm', 'close');


select s.id, b.id, (select id from public.staff where staff_code = 'A-M1') from public.staff s, public.badges b
 where (s.staff_code, b.slug) in (('A-01','fryer-whisperer'), ('A-04','deep-diver'), ('A-02','mentor'), ('A-06','handover-hero'), ('A-08','no-shortcuts'));


select (select id from public.channels where kind = 'direct'), id from public.staff where staff_code in ('A-M1', 'A-03');
select m.id, so.staff_id from public.messages m join public.channels c on c.id = m.channel_id
  join public.staff_outlets so on (c.outlet_id is null or so.outlet_id = c.outlet_id)
 where m.is_memo and (abs(hashtext(so.staff_id::text || m.id::text)) % 10) < 7
on conflict do nothing;

-- Crowns: pending for every finished week; Ivan (owner) has signed off all but last week (EXAMPLE),
-- including one override. Signing off locks that week's hours.
select public.crown_weekly_winners();
update public.weekly_crowns c set status = 'confirmed', confirmed_by = (select id from public.staff where staff_code = 'OWNER'), confirmed_at = c.crowned_at
 where c.week_start < public.perth_week_start() - 7;
update public.weekly_crowns c set winner_id = x.staff_id, overridden = true, override_by = (select id from public.staff where staff_code = 'OWNER'),
       override_reason = 'EXAMPLE: covered three extra closes for a sick teammate'
  from public.weekly_board x
 where x.outlet_id = c.outlet_id and x.week_start = c.week_start and x.position = 2
   and c.outlet_id = (select id from public.outlets where slug = 'boughshed-kitchen') and c.week_start = public.perth_week_start() - 21;

